package com.emergencylight.app

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioDeviceInfo
import android.media.AudioFormat
import android.media.AudioManager
import android.media.AudioTrack
import android.os.Process
import kotlin.math.PI
import kotlin.math.max
import kotlin.math.sin

/**
 * Plays a siren that is generated by code while the app runs (no sound files).
 *
 * Sound: sine wave, 44100 Hz, 16-bit mono.
 * Frequency sweeps linearly 900 Hz -> 2400 Hz in 0.5 s, then 2400 Hz -> 900 Hz in 0.5 s (1 cycle = 1 s).
 * Amplitude = 85% of maximum. The phase is carried over between samples, so there are no clicks.
 */
class SirenPlayer(context: Context) {

    private val audioManager = context.getSystemService(Context.AUDIO_SERVICE) as? AudioManager

    @Volatile
    private var running = false
    private var track: AudioTrack? = null
    private var thread: Thread? = null

    val isPlaying: Boolean get() = running

    /** Starts the siren. Returns false if the audio output could not be created. */
    fun start(): Boolean {
        if (running) return true
        return try {
            val minBuf = AudioTrack.getMinBufferSize(SAMPLE_RATE, AudioFormat.CHANNEL_OUT_MONO, AudioFormat.ENCODING_PCM_16BIT)
            // Small buffer = fast start and fast stop (about 50 ms).
            val bufferBytes = max(minBuf, CHUNK_FRAMES * 2 * 2)
            val t = AudioTrack.Builder()
                .setAudioAttributes(
                    AudioAttributes.Builder()
                        // ALARM usage = plays even when the phone is on silent / vibrate.
                        .setUsage(AudioAttributes.USAGE_ALARM)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                        .build()
                )
                .setAudioFormat(
                    AudioFormat.Builder()
                        .setSampleRate(SAMPLE_RATE)
                        .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                        .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                        .build()
                )
                .setTransferMode(AudioTrack.MODE_STREAM)
                .setBufferSizeInBytes(bufferBytes)
                .setPerformanceMode(AudioTrack.PERFORMANCE_MODE_LOW_LATENCY)
                .build()
            if (t.state != AudioTrack.STATE_INITIALIZED) {
                t.release()
                return false
            }
            // Force the phone's own loudspeaker, even if headphones or Bluetooth are connected.
            builtInSpeaker()?.let { t.setPreferredDevice(it) }

            val generator = SirenGenerator()
            val first = ShortArray(CHUNK_FRAMES)
            generator.fill(first)
            t.write(first, 0, first.size) // pre-fill so sound starts at once
            t.play()

            track = t
            running = true
            thread = Thread({
                try {
                    Process.setThreadPriority(Process.THREAD_PRIORITY_URGENT_AUDIO)
                } catch (e: Exception) {
                    // ignore
                }
                val buf = ShortArray(CHUNK_FRAMES)
                while (running) {
                    generator.fill(buf)
                    var offset = 0
                    while (running && offset < buf.size) {
                        val n = try { t.write(buf, offset, buf.size - offset) } catch (e: Exception) { -1 }
                        if (n <= 0) {
                            try { Thread.sleep(10) } catch (e: InterruptedException) { break }
                            break
                        }
                        offset += n
                    }
                }
            }, "siren").also { it.start() }
            true
        } catch (e: Exception) {
            running = false
            false
        }
    }

    /** Stops the siren immediately (well under 0.3 s). */
    fun stop() {
        running = false
        val t = track
        track = null
        try {
            t?.pause()
            t?.flush()
        } catch (e: Exception) {
            // ignore
        }
        try {
            thread?.join(300)
        } catch (e: Exception) {
            // ignore
        }
        thread = null
        try {
            t?.stop()
        } catch (e: Exception) {
            // ignore
        }
        try {
            t?.release()
        } catch (e: Exception) {
            // ignore
        }
    }

    private fun builtInSpeaker(): AudioDeviceInfo? = try {
        audioManager?.getDevices(AudioManager.GET_DEVICES_OUTPUTS)
            ?.firstOrNull { it.type == AudioDeviceInfo.TYPE_BUILTIN_SPEAKER }
    } catch (e: Exception) {
        null
    }

    /** Generates the sweeping sine wave, keeping the phase continuous between chunks. */
    private class SirenGenerator {
        private var phase = 0.0
        private var position = 0 // sample index inside the 1-second cycle

        fun fill(buffer: ShortArray) {
            val half = SAMPLE_RATE / 2
            for (i in buffer.indices) {
                val freq = if (position < half) {
                    LOW_HZ + (HIGH_HZ - LOW_HZ) * position / half.toDouble()
                } else {
                    HIGH_HZ - (HIGH_HZ - LOW_HZ) * (position - half) / half.toDouble()
                }
                phase += TWO_PI * freq / SAMPLE_RATE
                if (phase >= TWO_PI) phase -= TWO_PI
                buffer[i] = (sin(phase) * AMPLITUDE).toInt().toShort()
                position++
                if (position >= SAMPLE_RATE) position = 0
            }
        }
    }

    companion object {
        private const val SAMPLE_RATE = 44100
        private const val CHUNK_FRAMES = 1024
        private const val LOW_HZ = 900.0
        private const val HIGH_HZ = 2400.0
        private const val AMPLITUDE = 0.85 * 32767.0
        private const val TWO_PI = 2.0 * PI
    }
}
